mapper.update:
UPDATE ai_chat_memory_summary
SET user_id = #{summary.userId}, summary = #{summary.summary},
    last_message_id = #{summary.lastMessageId}, version = version + 1,
    summary_msg_count = #{summary.summaryMsgCount},
    detail_msg_count = #{summary.detailMsgCount}, updated_at = NOW()
WHERE conversation_id = #{summary.conversationId}
  AND version = #{expectedVersion}
  AND summary_msg_count = #{expectedWatermark}
  AND summary_msg_count < #{summary.summaryMsgCount}
  AND detail_msg_count <= #{summary.detailMsgCount}
  AND EXISTS (SELECT 1 FROM ai_chat_memory m
              WHERE m.conversation_id = #{summary.conversationId} AND m.id = #{summary.lastMessageId})
